function getUniqueCategories(products) {
    const categorySet = new Set();
  
    // Recorremos los productos y sus categorías
    products.forEach(product => {
      product.categories.forEach(category => {
        // Crear un identificador único para evitar duplicados
        const categoryKey = `${category.id}-${category.name}`;
        if (!categorySet.has(categoryKey)) {
          categorySet.add(categoryKey);
        }
      });
    });
  
    // Convertimos el conjunto a un array de objetos
    const uniqueCategories = Array.from(categorySet).map(key => {
      const [id, name] = key.split('-');
      return { id: parseInt(id), name };
    });
  
    return uniqueCategories;
  }
  
  // Ejecutar la función
  const uniqueCategoriesList = getUniqueCategories(products);
  console.log(uniqueCategoriesList);